const items = $input.all();

// If no items or date fields missing, pass everything through
const recentFiles = items.filter(item => {
  // No date fields returned by Google Drive node — pass all through
  if (!item.json.modifiedTime && !item.json.createdTime) return true;

  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const modified = new Date(item.json.modifiedTime || item.json.createdTime);
  return modified > sevenDaysAgo;
});

if (recentFiles.length === 0) {
  return [{ 
    json: { 
      id: null, 
      name: 'No meeting notes found this week'
    } 
  }];
}

return recentFiles.map(f => ({ json: f.json }));

const doc = $input.first().json;
const title = doc.title || 'Untitled Meeting Notes';
const content = doc.body?.content || [];

let text = '';

for (const block of content) {
  // Handle paragraphs
  if (block.paragraph) {
    const elements = block.paragraph.elements || [];
    for (const el of elements) {
      if (el.textRun?.content) {
        text += el.textRun.content;
      }
    }
  }
  // Handle tables
  if (block.table) {
    const rows = block.table.tableRows || [];
    for (const row of rows) {
      const cells = row.tableCells || [];
      const cellTexts = cells.map(cell => {
        return (cell.content || [])
          .flatMap(b => (b.paragraph?.elements || [])
          .map(el => el.textRun?.content || ''))
          .join('').trim();
      });
      text += cellTexts.join(' | ') + '\n';
    }
  }
}

// Clean up whitespace
const cleanText = text.replace(/\n{3,}/g, '\n\n').trim();

// Limit to 3000 chars per doc
const truncated = cleanText.length > 3000
  ? cleanText.substring(0, 8000) + '\n[truncated...]'
  : cleanText;

return [{
  json: {
    title,
    content: truncated,
    charCount: cleanText.length,
    docId: doc.documentId
  }
}];

const items = $input.all();

if (!items.length || items[0].json.content === 'No meeting notes found this week.') {
  return [{
    json: {
      meetingNotesContext: '=== Meeting Notes (Last 7 days) ===\nNo meeting notes found this week.'
    }
  }];
}

let collated = '=== Meeting Notes (Last 7 days) ===\n';

for (const item of items) {
  const title = item.json.title || 'Untitled';
  const content = item.json.content || '';

  if (content) {
    collated += `\n--- ${title} ---\n${content}\n`;
  }
}

return [{
  json: {
    meetingNotesContext: collated,
    totalDocs: items.filter(i => i.json.docId).length
  }
}];

const data = $input.first().json;
const files = data.files || [];

if (files.length === 0) {
  return [{
    json: {
      id: null,
      name: 'No new meeting notes found',
      modifiedTime: null
    }
  }];
}

console.log(`Found ${files.length} meeting notes`);

return files.map(f => ({ json: f }));

const blocks = $('GD: Fetch Collector Prompt').first().json.results || [];
const collatedNotes = $('GD: Collate Meeting Notes').first().json;
const trigger = $('Input: Receive Trigger').first().json;

// Extract Collector Base Prompt from Notion
let collectorPrompt = '';
let inCollectorSection = false;

for (const block of blocks) {
  if (block.type === 'heading_2') {
    const text = block.heading_2?.rich_text?.[0]?.plain_text || '';
    if (text.includes('Collector Base Prompt')) {
      inCollectorSection = true;
      continue;
    }
    if (inCollectorSection) break;
  }
  if (inCollectorSection && block.type === 'code') {
    collectorPrompt = block.code?.rich_text?.map(r => r.plain_text).join('') || '';
    break;
  }
}

if (!collectorPrompt) {
  collectorPrompt = 'ERROR: Collector Base Prompt not found in Prompt Library';
}

// Get raw content and file map
const rawContent = collatedNotes.meetingNotesContext || 'No meeting notes found.';
let formattedContent = rawContent;

const fileItems = $('GD: Parse Files').all();
const fileMap = {};
for (const file of fileItems) {
  const title = file.json.name || '';
  const id = file.json.id || '';
  if (id) {
    fileMap[title] = `https://docs.google.com/document/d/${id}/edit`;
  }
}

// Inject URLs into collated content
for (const [title, url] of Object.entries(fileMap)) {
  formattedContent = formattedContent.replace(
    `--- ${title} ---`,
    `--- ${title} ---\nSource URL: ${url}`
  );
}

const totalDocs = collatedNotes.totalDocs || 0;
const dateToday = trigger.dateToday || new Date().toISOString().split('T')[0];
const dateLastMonday = trigger.dateLastMonday || dateToday;

const finalPrompt = collectorPrompt
  .replace('[raw source data injected here]', formattedContent)
  .replace('[source_name]', 'google_drive');

return [{
  json: {
    userMessage: finalPrompt,
    totalDocs,
    dateToday,
    dateLastMonday
  }
}];

const response = $input.first().json;
const raw = response.content?.[0]?.text || '';
const context = $('GD: Build Collector Context').first().json;

const clean = raw
  .replace(/^```json\n?/, '')
  .replace(/\n?```$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    source: 'google_drive',
    signals: [],
    itemCount: 0,
    dateRange: `${context.dateLastMonday} to ${context.dateToday}`,
    status: 'error',
    error: e.message
  };
}

const output = {
  source: parsed.source || 'google_drive',
  signals: parsed.signals || [],
  itemCount: parsed.itemCount || parsed.signals?.length || 0,
  dateRange: parsed.dateRange || `${context.dateLastMonday} to ${context.dateToday}`,
  status: parsed.status || (parsed.signals?.length > 0 ? 'success' : 'empty')
};

console.log(`GD collector: ${output.signals.length} signals extracted`);
console.log(`High confidence: ${output.signals.filter(s => s.confidence === 'high').length}`);

return [{ json: output }];
